import{_ as o,l as p,o as e,c as m,v as r,p as l,x as t,d as s,i as n,S as h}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"最弱前置条件","description":"","frontmatter":{"title":"最弱前置条件","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/weakest-precondition.md","filePath":"cs/weakest-precondition.md","lastUpdated":1789023840000}'),d={name:"cs/weakest-precondition.md"};function _(c,a,w,S,f,P){const i=p("Mermaid");return e(),m("div",null,[a[1]||(a[1]=r('<h1 id="最弱前置条件" tabindex="-1">最弱前置条件 <a class="header-anchor" href="#最弱前置条件" aria-label="Permalink to &quot;最弱前置条件&quot;">​</a></h1><div class="epigraph"><p>$\\mathrm{wp}(S,Q)$ 是使 $S$ 执行后 $Q$ 成立的最弱前置。Dijkstra 用它定义语义：从后往前算，循环变成不动点。</p><footer>—— 据 Dijkstra, A Discipline of Programming, 1976；Winskel 整理</footer></div><p>上一课<a href="/cs/hoare-logic">Hoare 逻辑</a> 的三元组要人提供 \\(P\\) 与不变式。缺口是<strong>最弱前置</strong> \\(\\mathrm{wp}(S,Q)\\)：\\(\\{P\\}S\\{Q\\}\\) 部分正确当且仅当 \\(P\\Rightarrow\\mathrm{wp}(S,Q)\\)（在终止版本下还有「必停」）。本课给赋值、顺序、if 的等式；while 用 \\(\\mu\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\mathrm{wp}(x:=e,Q)=Q[e/x]\\)。\\(\\mathrm{wp}(S_1;S_2,Q)=\\mathrm{wp}(S_1,\\mathrm{wp}(S_2,Q))\\)。\\(\\mathrm{wp}(\\mathrm{if}\\ b\\ S_1\\ S_2,Q)=(b\\land\\mathrm{wp}(S_1,Q))\\lor(\\neg b\\land\\mathrm{wp}(S_2,Q))\\)。循环：\\(\\mathrm{wp}(\\mathrm{while}\\ b\\ S,Q)\\) 是最弱的 \\(I\\)，满足 \\(I\\iff(\\neg b\\land Q)\\lor(b\\land\\mathrm{wp}(S,I))\\)——即某个单调变换的最弱不动点 / 最大前不动点，说法随部分/完全正确而变。本课要「循环 = 不动点方程」，计算下一课 Knaster–Tarski。</p><p>\\(\\mathrm{sp}\\)（最强后置）从前往后，对符号执行更亲。点名。</p><h3 id="最弱不是「最容易证」" tabindex="-1">最弱不是「最容易证」 <a class="header-anchor" href="#最弱不是「最容易证」" aria-label="Permalink to &quot;最弱不是「最容易证」&quot;">​</a></h3><p>最弱 \\(P\\) 允许最多起始状态，公式可能更复杂。人写的不变式往往强于 \\(\\mathrm{wp}\\)，但更好证。</p><p><span class="marginnote">Dijkstra 1976；谓词变换器。ESC/Java、Boogie 把 VC 生成建成工具，本课不写前端。完全正确的 wp 要求体降低变式。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对无循环程序从后往前算一遍 \\(\\mathrm{wp}\\)。指出循环必须近似不动点或给不变式当归纳假设。对照赋值公理：它正是 \\(\\mathrm{wp}\\) 的特例。</p>',11)),(e(),l(h,null,{default:t(()=>[n(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8E%E6%9D%A1%E4%BB%B6%20Q%22%5D%20--%3E%20WP%5B%22wp(S%2CQ)%22%5D%0A%20%20WP%20--%3E%20PRE%5B%22%E5%90%88%E6%B3%95%E5%89%8D%E7%BD%AE%20P%20%E2%87%92%20wp%22%5D%0A%20%20WP%20--%3E%20FIX%5B%22while%EF%BC%9A%E4%B8%8D%E5%8A%A8%E7%82%B9%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>验证条件生成：用户给不变式，工具检查体保持、进入、退出，即若干 \\(\\mathrm{wp}\\) 蕴含。SMT 后课吃这些公式。没有不变式则要对循环求不动点——有限域上即模型检验的前/后像，再后课。</p><p>可靠：谓词变换器与操作语义一致。</p><p>Dijkstra 的卫式命令：\\(\\mathrm{wp}(S_0\\square S_1,Q)=\\mathrm{wp}(S_0,Q)\\land\\mathrm{wp}(S_1,Q)\\) 当两条都可执行。魔命令 \\(\\mathbf{abort}\\) 的 wp 是假。循环的近似：从假迭代 \\(\\Phi\\) 得到最弱不变式的不足逼近，有限抽象域上会停。VC 生成把用户不变式当归纳假设，检查几条蕴含。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定义卫式命令全集，不引入概率 wp。不把抽象解释写完。后课默认：无环程序的 \\(P\\) 可算；循环要不变式或不动点。下一课格上的 Knaster–Tarski。</p><p>无环程序的 \\(P\\) 可从后往前算；循环变成谓词变换器的不动点。用户不变式是归纳假设，工具只检查蕴含。下一课用格定理保证最小/最大不动点存在。</p><p>上一课留下的缺口在本课收口；「最弱前置条件」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(\\mathrm{wp}(S,Q)\\) 是使后条件成立的最弱前置。</li><li>赋值、顺序、if 有等式；while 是不动点。</li><li>Hoare 三元组 \\(=P\\Rightarrow\\mathrm{wp}\\)。</li><li>出处：Dijkstra, 1976；Winskel。</li></ul>',10))])}const b=o(d,[["render",_]]);export{k as __pageData,b as default};
